import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    try:
        with urllib.request.urlopen(API_URL) as response:
            data = response.read().decode('utf-8')

            # Try parsing as JSON first
            try:
                json_data = json.loads(data)
                if isinstance(json_data, dict):
                    # Look for common IP fields
                    for key in ['ip', 'IP', 'address', 'Address', 'public_ip', 
                                'myip', 'client_ip', 'remote_addr']:
                        if key in json_data:
                            value = str(json_data[key])
                            match = re.search(IP_REGEX, value)
                            if match:
                                return match.group()

                    # If no specific field found, scan entire JSON
                    full_text = json.dumps(json_data)
            except json.JSONDecodeError:
                full_text = data

            match = re.search(IP_REGEX, full_text)
            if match:
                return match.group()

            # If no IP found in response, raise an error
            if data:
                raise ValueError(f"No valid IP address found in API response: {data[:200]}")
            else:
                raise ValueError("No data received from API")

    except urllib.error.URLError as e:
        raise ValueError(f"API request failed: {e.reason}")
    except Exception as e:
        raise ValueError(f"API request failed: {str(e)}")
