import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluates each item (files and directories) in a given directory against specified conditions.

    Parameters:
        dir_path (str): Path to the directory to evaluate.
        predicates (list): List of condition predicates. Each predicate can be:
            - A string pattern to match item names (regex).
            - A callable that takes an item name and returns a bool.
            - A tuple (type_filter, pattern/callable) where type_filter is 'file', 'dir', or 'all'.

    Returns:
        dict: A dictionary with directory items as keys and the results of condition checks as values.

    Raises:
        ValueError: If no valid predicates are provided.
        FileNotFoundError: If the specified directory does not exist or is not a directory.
    """
    if not isinstance(predicates, list):
        raise ValueError("No valid predicates are provided.")

    valid_predicates = []
    seen = set()

    def make_key(pred):
        if callable(pred):
            return id(pred)
        if isinstance(pred, str):
            return ('pattern', pred)
        if isinstance(pred, tuple) and len(pred) == 2:
            return ('typed', pred[0], pred[1])
        return None

    def compile_predicate(pred):
        if callable(pred):
            return pred
        if isinstance(pred, str):
            pattern = re.compile(pred)
            return lambda name: pattern.search(name) is not None
        if isinstance(pred, tuple) and len(pred) == 2:
            type_filter, condition = pred
            inner = compile_predicate(condition)
            if type_filter == 'file':
                return lambda name: os.path.isfile(os.path.join(dir_path, name)) and inner(name)
            elif type_filter == 'dir':
                return lambda name: os.path.isdir(os.path.join(dir_path, name)) and inner(name)
            elif type_filter == 'all':
                return inner
            else:
                return None
        return None

    for pred in predicates:
        key = make_key(pred)
        if key is None:
            continue
        if key in seen:
            continue
        compiled = compile_predicate(pred)
        if compiled is None:
            continue
        seen.add(key)
        valid_predicates.append(compiled)

    if not valid_predicates:
        raise ValueError("No valid predicates are provided.")

    path = Path(dir_path)
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"The directory '{dir_path}' does not exist or is not a directory.")

    results = {}
    for item in path.iterdir():
        name = item.name
        for pred in valid_predicates:
            results[name] = pred(name)
            # If any predicate matches, we record the result; 
            # if multiple predicates, the last one's result overwrites.
            # Clarification: "results of condition checks" plural suggests all?
            # But dict item-key can only hold one value. We'll return whether the item matches any predicate.
            # Actually, re-reading: "results of condition checks" — ambiguous.
            # Common interpretation: boolean indicating if item matches any predicate.
            # Let's implement: item matches if any predicate returns True.
        # We need to recompute: any matches
        matched = any(pred(name) for pred in valid_predicates)
        results[name] = matched

    return results
