import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    try:
        with urllib.request.urlopen(API_URL) as response:
            data = response.read()

        if response.status != 200:
            raise Exception(f"API request failed: {response.status} {response.reason}")

        try:
            result = json.loads(data)
        except json.JSONDecodeError:
            text = data.decode('utf-8', errors='replace')
            match = re.search(IP_REGEX, text)
            if match:
                return match.group(0)
            raise Exception("Failed to retrieve IP address from API response")

        if isinstance(result, str):
            match = re.search(IP_REGEX, result)
            if match:
                return match.group(0)

        if isinstance(result, dict):
            ip = result.get('ip') or result.get('address') or result.get('public_ip')
            if isinstance(ip, str):
                match = re.search(IP_REGEX, ip)
                if match:
                    return match.group(0)

        if isinstance(result, list) and len(result) > 0:
            first = result[0]
            if isinstance(first, str):
                match = re.search(IP_REGEX, first)
                if match:
                    return match.group(0)
            elif isinstance(first, dict):
                ip = first.get('ip') or first.get('address') or first.get('public_ip')
                if isinstance(ip, str):
                    match = re.search(IP_REGEX, ip)
                    if match:
                        return match.group(0)

        raise Exception("Failed to retrieve IP address from API response")

    except urllib.error.URLError as e:
        raise Exception(f"API request failed: {e.reason if hasattr(e, 'reason') else str(e)}")
    except Exception as e:
        raise Exception(f"API request failed: {str(e)}")
