from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.exists() or not directory.is_dir():
        raise FileNotFoundError(f"The specified directory does not exist or is not a directory: {dir_path}")

    if not predicates:
        raise ValueError("No valid predicates are provided.")

    deduplicated_predicates = []
    seen = set()

    for pred in predicates:
        if pred not in seen:
            seen.add(pred)
            deduplicated_predicates.append(pred)

    if not deduplicated_predicates:
        raise ValueError("No valid predicates are provided.")

    results = {}

    for item in directory.iterdir():
        name = item.name
        checks = []

        for predicate in deduplicated_predicates:
            if callable(predicate):
                check_result = predicate(name)
            elif isinstance(predicate, str):
                if predicate.startswith("regex:"):
                    pattern = predicate[6:]
                    check_result = bool(re.match(pattern, name))
                elif predicate.startswith("startswith:"):
                    prefix = predicate[11:]
                    check_result = name.startswith(prefix)
                elif predicate.startswith("endswith:"):
                    suffix = predicate[7:]
                    check_result = name.endswith(suffix)
                elif predicate.startswith("contains:"):
                    substring = predicate[9:]
                    check_result = substring in name
                elif predicate == "is_file":
                    check_result = item.is_file()
                elif predicate == "is_dir":
                    check_result = item.is_dir()
                else:
                    check_result = False

                checks.append(check_result)
            else:
                check_result = False
                checks.append(check_result)

        results[name] = checks

    return results
