import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    # Validate predicates
    if not predicates:
        raise ValueError("No valid predicates are provided.")

    # Deduplicate predicates while preserving order
    seen = set()
    unique_predicates = []
    for pred in predicates:
        if pred not in seen:
            seen.add(pred)
            unique_predicates.append(pred)

    # Validate directory
    path = Path(dir_path)
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"The directory '{dir_path}' does not exist or is not a directory.")

    results = {}
    for item in path.iterdir():
        name = item.name
        # Evaluate each predicate against the item name
        checks = []
        for pred in unique_predicates:
            if callable(pred):
                checks.append(pred(name))
            elif isinstance(pred, str):
                # Treat string predicates as regex patterns
                checks.append(bool(re.search(pred, name)))
            else:
                raise ValueError(f"Unsupported predicate type: {type(pred)}")

        results[name] = checks

    return results
