import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    """
    Get the public IP address of the current host from an API.

    Parameters:
    API_URL (str): The URL of the API to fetch the public IP address

    Returns:
    str: The public IP address if successful

    Raises:
    Exception: If the API request fails with the error message
    """
    try:
        with urllib.request.urlopen(API_URL, timeout=10) as response:
            data = response.read().decode('utf-8')

            # Try to parse as JSON first
            try:
                json_data = json.loads(data)
                # Handle common API response formats
                if isinstance(json_data, dict):
                    # Try common field names
                    for key in ['ip', 'address', 'public_ip', 'myip', 'ip_address']:
                        if key in json_data:
                            ip = json_data[key]
                            if isinstance(ip, str) and re.match(IP_REGEX, ip):
                                return ip
                    # If no known field found, return the first matching IP in the JSON
                    json_str = json.dumps(json_data)
                    match = re.search(IP_REGEX, json_str)
                    if match:
                        return match.group(0)
                elif isinstance(json_data, list) and len(json_data) > 0:
                    # Try first element
                    first = json_data[0]
                    if isinstance(first, str) and re.match(IP_REGEX, first):
                        return first
            except json.JSONDecodeError:
                pass

            # If not JSON, try to find IP in plain text
            match = re.search(IP_REGEX, data)
            if match:
                return match.group(0)

            # If no IP found in response
            raise Exception(f"Could not find IP address in API response: {data}")

    except urllib.error.URLError as e:
        raise Exception(f"API request failed: {str(e.reason)}")
    except urllib.error.HTTPError as e:
        raise Exception(f"API request failed with HTTP error {e.code}: {e.reason}")
    except Exception as e:
        raise Exception(f"Error: {str(e)}")
