    letters = test.split()

    # Count occurrences of each letter
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1

    # If no letters were counted, return empty dict
    if not counts:
        return {}

    # Find maximum count
    max_count = max(counts.values())

    # Return only letters with maximum count
