from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    # Check if directory exists and is a directory
    if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
        raise FileNotFoundError(f"Directory {dir_path} does not exist or is not a directory")

    # Deduplicate predicates while maintaining order
    seen = set()
    unique_predicates = []
    for pred in predicates:
        pred_key = str(pred)
        if pred_key not in seen:
            seen.add(pred_key)
            unique_predicates.append(pred)

    # Validate that we have at least one valid predicate
    if not unique_predicates:
        raise ValueError("No valid predicates are provided")

    # Get all items in the directory (only names, not full paths)
    items = os.listdir(dir_path)

    # Evaluate each item against predicates
    result = {}
    for item in items:
        results = []
        for pred in unique_predicates:
            if isinstance(pred, str):
                # Try to match as regex
                try:
                    match = re.match(pred, item)
                    results.append(bool(match))
                except:
                    results.append(False)
            elif callable(pred):
                # Call the predicate function
                try:
                    results.append(pred(item))
                except:
                    results.append(False)
            else:
                # Invalid predicate type
                results.append(False)

        result[item] = results

    return result
