import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    # Validate directory exists and is a directory
    path = Path(dir_path)
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"Directory not found or not a directory: {dir_path}")

    # Deduplicate and validate predicates
    seen = set()
    valid_predicates = []

    for pred in predicates:
        if pred is None:
            continue

        # Create a hashable key for deduplication based on predicate content
        if callable(pred):
            pred_key = id(pred)
        elif isinstance(pred, str):
            pred_key = f"str:{pred}"
        elif isinstance(pred, dict):
            # Sort items to ensure consistent key for same predicate dicts
            pred_key = str(sorted(pred.items()))
        else:
            continue  # Skip invalid predicate types

        if pred_key not in seen:
            seen.add(pred_key)
            valid_predicates.append(pred)

    if not valid_predicates:
        raise ValueError("No valid predicates are provided")

    # Evaluate each item in directory against all predicates
    result = {}
    for item in path.iterdir():
        item_name = item.name
        item_results = []

        for pred in valid_predicates:
            if callable(pred):
                # Call the predicate function with the item name
                item_results.append(bool(pred(item_name)))
            elif isinstance(pred, str):
                # String predicate: check if it's contained in the name
                item_results.append(pred in item_name)
            elif isinstance(pred, dict):
                match = True
                pred_type = pred.get('type', 'regex')

                if pred_type == 'regex':
                    pattern = pred.get('pattern', '')
                    match = bool(re.search(pattern, item_name))
                elif pred_type == 'extension':
                    ext = pred.get('extension', '')
                    match = item.suffix == ext
                elif pred_type == 'length':
                    min_len = pred.get('min_length', 0)
                    max_len = pred.get('max_length', float('inf'))
                    match = min_len <= len(item_name) <= max_len
                elif pred_type == 'startswith':
                    match = item_name.startswith(pred.get('prefix', ''))
                elif pred_type == 'endswith':
                    match = item_name.endswith(pred.get('suffix', ''))
                elif pred_type == 'is_file':
                    match = item.is_file() == pred.get('value', False)
                elif pred_type == 'is_dir':
                    match = item.is_dir() == pred.get('value', False)

                item_results.append(match)

        result[item_name] = item_results

    return result
