# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    try:
        with urllib.request.urlopen(API_URL, timeout=10) as response:
            data = response.read().decode('utf-8')

        # Try parsing JSON first
        try:
            result = json.loads(data)
            # Handle common JSON API responses
            if isinstance(result, dict):
                for value in result.values():
                    if isinstance(value, str) and re.match(IP_REGEX, value):
                        return value
                # If no IP found in dict values, use whole response
                data = data
            elif isinstance(result, list):
                for item in result:
                    if isinstance(item, str) and re.match(IP_REGEX, item):
                        return item
        except json.JSONDecodeError:
            pass

        # Fallback: search raw response for IP address
        match = re.search(IP_REGEX, data)
        if match:
            return match.group(0)

        raise ValueError("No valid public IP address found in API response")

    except urllib.error.URLError as e:
        raise ValueError(f"API request failed: {e.reason}") from e
    except urllib.error.HTTPError as e:
        raise ValueError(f"API request failed with status {e.code}") from e
    except Exception as e:
        raise ValueError(f"API request failed: {str(e)}") from e
