import re
from datetime import time
from statistics import mean

def task_func(logs: list):
    """
    Analyze logs for error occurrences and calculate the average time of occurrence.

    Args:
        logs: A list of log strings, each containing a timestamp and potentially an error message.

    Returns:
        dict: {
            "list": list of time objects when errors occurred,
            "time": average time of error occurrence, or None if no errors.
        }
    """
    time_pattern = re.compile(r'(\d{2}:\d{2}(?::\d{2})?)')
    error_pattern = re.compile(r'\berror\b', re.IGNORECASE)

    error_times = []

    for log in logs:
        if error_pattern.search(log):
            match = time_pattern.search(log)
            if match:
                time_str = match.group(1)
                try:
                    error_times.append(time.fromisoformat(time_str))
                except ValueError:
                    continue

    if not error_times:
        return {"list": [], "time": None}

    average_time = mean(error_times)
    return {"list": error_times, "time": average_time}
