import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    # Compile and deduplicate predicates, preserving order.
    compiled_predicates = []
    seen = set()

    for predicate in predicates:
        if not isinstance(predicate, str) or not predicate.strip():
            continue

        if predicate in seen:
            continue

        try:
            pattern = re.compile(predicate)
        except re.error:
            continue

        seen.add(predicate)
        compiled_predicates.append(pattern)

    if not compiled_predicates:
        raise ValueError("No valid predicates are provided.")

    path = Path(dir_path)

    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(
            f"The specified directory does not exist or is not a directory: {dir_path}"
        )

    results = {}

    for item in os.listdir(dir_path):
        item_path = path / item
        if not item_path.exists():
            continue

        conditions = [bool(pattern.match(item)) for pattern in compiled_predicates]
        results[item] = conditions

    return results
