import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    seen = set()
    compiled_predicates = []

    for pred in predicates:
        if not isinstance(pred, str):
            continue

        pred = pred.strip()

        if not pred:
            continue

        if pred in seen:
            continue

        seen.add(pred)

        try:
            compiled_predicates.append(re.compile(pred))
        except re.error:
            continue

    if not compiled_predicates:
        raise ValueError("No valid predicates provided.")

    path = Path(dir_path)

    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(
            f"The specified directory does not exist or is not a directory: {dir_path}"
        )

    results = {}

    for entry in path.iterdir():
        name = entry.name
        checks = []

        for pattern in compiled_predicates:
            checks.append(bool(pattern.fullmatch(name)))

        results[name] = checks

    return results
```

